const cube=`<path d="M0-58 56-27V37L0 68-56 37V-27Z" fill="url(#cube-left)" stroke="#c8a5ff" stroke-width="2" stroke-linejoin="round"/><path d="m0-58 56 31L0 5-56-32Z" fill="url(#cube-top)"/><path d="M0 5 56-27V37L0 68Z" fill="url(#cube-right)"/><path d="M0 5v63M-56-27 0 5 56-27" fill="none" stroke="#e0c9ff" stroke-width="2"/><path d="m-33-26 33-18 30 17L0-9Z" fill="none" stroke="#ead5ff" opacity=".55"/><path d="m16 20 24-13m-24 26 15-8" stroke="#d2b0fb" opacity=".6" stroke-width="3" stroke-linecap="round"/>`;
