 <g id="cosmic-ring" transform="translate(1100 363)"><ellipse rx="325" ry="205" stroke="#6d4d88" stroke-width="1" fill="none" opacity=".3"/><ellipse rx="345" ry="220" stroke="#86619f" stroke-width=".7" fill="none" opacity=".15"/><path d="M-330 0h660M0-208v416" stroke="#76548b" opacity=".1"/><circle cx="0" cy="-205" r="3" fill="#ac7bd0"/><circle cx="325" r="3" fill="#ac7bd0"/></g>
